"""Real-process watchdog tests, generated bytes only; no Vulkan or camera."""
import ctypes
import json
import os
from pathlib import Path
import signal
import subprocess
import sys
import tempfile
import time
import unittest

from scripts import capture_watchdog as watchdog


class WatchdogTests(unittest.TestCase):
    def run_worker(self, source, timeout=1, requested=None):
        return watchdog.supervise([sys.executable, '-c', source], timeout=timeout,
                                  requested=[] if requested is None else requested)

    def test_success_is_process_exit_not_resource_cleanup(self):
        report = self.run_worker("print('done')")
        self.assertEqual(report['exit_code'], 0, report)
        self.assertTrue(report['worker_reaped'])
        self.assertFalse(report['termination_requested'])
        self.assertFalse(report['resource_cleanup_confirmed'])
        self.assertFalse(report['deployment_ready'])

    def test_failure_and_native_signal(self):
        for source, code in [('raise SystemExit(17)', 17),
                             ('import os, signal; os.kill(os.getpid(), signal.SIGKILL)', -9)]:
            report = self.run_worker(source)
            self.assertEqual(report['exit_code'], 1)
            self.assertEqual(report['worker_exit_code'], code)
            self.assertTrue(report['worker_reaped'])

    def test_hang_and_closed_pipes_still_have_deadline(self):
        for prefix in ('', 'os.close(1); os.close(2);'):
            report = self.run_worker('import os, signal, time; signal.signal(signal.SIGTERM, signal.SIG_IGN);'
                                     + prefix + 'time.sleep(30)', timeout=.15)
            self.assertEqual(report['reason'], 'worker_deadline', report)
            self.assertTrue(report['kill_requested'])
            self.assertTrue(report['worker_reaped'])
            self.assertLess(report['elapsed_ms'], 2000)
            with self.assertRaises(ProcessLookupError):
                os.kill(report['worker_pid'], 0)

    def test_both_output_streams_bounded(self):
        for fd in (1, 2):
            report = self.run_worker(f'import os\nwhile True: os.write({fd}, b"x" * 8192)')
            self.assertEqual(report['reason'], 'worker_output_limit', report)
            self.assertLessEqual(len(report['stdout']), watchdog.MAX_OUTPUT)
            self.assertLessEqual(len(report['stderr']), watchdog.MAX_OUTPUT)
            self.assertTrue(report['worker_reaped'])

    def test_launch_failure_and_cancel_before_launch(self):
        report = watchdog.supervise(['/nonexistent/framejacker-worker'], timeout=1, requested=[])
        self.assertEqual(report['reason'], 'launch_or_read_failed')
        self.assertFalse(report['worker_started'])
        report = self.run_worker('raise Exception("must not run")', requested=[signal.SIGINT])
        self.assertEqual(report['exit_code'], 130)
        self.assertFalse(report['worker_started'])

    def test_invalid_deadlines_never_launch(self):
        for timeout in (0, -1, float('nan'), float('inf'), 16):
            with self.assertRaises(ValueError):
                self.run_worker('pass', timeout=timeout)

    def test_cli_has_no_live_capture_or_worker_override(self):
        for args, code in (([], 3), (['--allow-experimental-capture'], 2),
                           (['--worker', '/bin/true'], 2)):
            result = subprocess.run([sys.executable, 'scripts/capture_watchdog.py', *args],
                                    cwd=watchdog.ROOT, capture_output=True, timeout=3)
            self.assertEqual(result.returncode, code)

    def test_repeated_cancellation_does_not_interrupt_cleanup(self):
        body = '''
from scripts import capture_watchdog as w
import json, sys
with w.cancellation() as requested:
    report = w.supervise([sys.executable, '-c', sys.argv[1]], timeout=5, requested=requested)
print(json.dumps(report), flush=True)
'''
        with tempfile.TemporaryDirectory() as directory:
            marker = Path(directory) / 'ready'
            worker = ("import signal,time; from pathlib import Path; "
                      "signal.signal(signal.SIGTERM, signal.SIG_IGN); "
                      f"Path({str(marker)!r}).touch(); time.sleep(30)")
            process = subprocess.Popen([sys.executable, '-c', body, worker], cwd=watchdog.ROOT,
                                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            try:
                end = time.monotonic() + 3
                while not marker.exists() and time.monotonic() < end:
                    time.sleep(.01)
                self.assertTrue(marker.exists())
                process.send_signal(signal.SIGINT)
                time.sleep(.05)
                process.send_signal(signal.SIGTERM)
                output, error = process.communicate(timeout=3)
                self.assertFalse(error)
                report = json.loads(output)
                self.assertEqual(report['exit_code'], 130, report)
                self.assertTrue(report['worker_reaped'])
                self.assertTrue(report['kill_requested'])
            finally:
                if process.poll() is None:
                    process.kill()
                    process.communicate(timeout=3)

    def test_descendant_holding_pipes_is_killed_after_leader_exit(self):
        # Adopt/reap only our synthetic grandchild, not another task's processes.
        libc = ctypes.CDLL(None, use_errno=True)
        old = ctypes.c_int()
        self.assertEqual(libc.prctl(37, ctypes.byref(old), 0, 0, 0), 0)
        self.assertEqual(libc.prctl(36, 1, 0, 0, 0), 0)
        child = None
        try:
            report = self.run_worker('''
import os, signal, time
pid = os.fork()
if pid:
    print(pid, flush=True)
    os._exit(0)
signal.signal(signal.SIGTERM, signal.SIG_IGN)
time.sleep(30)
''', timeout=.2)
            child = int(report['stdout'])
            self.assertEqual(report['status'], 'timed_out', report)
            self.assertTrue(report['kill_requested'])
            end = time.monotonic() + 2
            while time.monotonic() < end:
                pid, status = os.waitpid(child, os.WNOHANG)
                if pid:
                    child = None
                    self.assertTrue(os.WIFSIGNALED(status))
                    break
                time.sleep(.01)
            self.assertIsNone(child)
        finally:
            if child:
                os.kill(child, signal.SIGKILL)
                os.waitpid(child, 0)
            libc.prctl(36, old.value, 0, 0, 0)

    @unittest.skipUnless(watchdog.FIXTURE.is_file(), 'build publication fixture first')
    def test_native_hangs_leave_publication_recovery_unconfirmed(self):
        for phase in ('startup', 'publication', 'shutdown'):
            with self.subTest(phase=phase), tempfile.TemporaryDirectory() as directory:
                source = Path(directory) / 'frames.shm'
                report = watchdog.supervise(
                    [str(watchdog.FIXTURE), '--create', str(source), '--seconds', '1',
                     '--watchdog-hang', phase], timeout=1.5, requested=[])
                self.assertEqual(report['reason'], 'worker_deadline', report)
                self.assertIn('synthetic_hang', report['stdout'])
                self.assertTrue(report['worker_reaped'])
                self.assertTrue(report['kill_requested'])
                self.assertFalse(report['resource_cleanup_confirmed'])
                self.assertEqual(source.exists(), phase != 'startup')
                if source.exists():
                    identity = source.stat()
                    retry = subprocess.run([str(watchdog.FIXTURE), '--create', str(source),
                                            '--seconds', '1'], capture_output=True, timeout=3)
                    self.assertEqual(retry.returncode, 1)
                    self.assertEqual(source.stat().st_ino, identity.st_ino)

    @unittest.skipUnless(watchdog.FIXTURE.is_file(), 'build publication fixture first')
    def test_native_generated_publication(self):
        report = watchdog.synthetic_check([])
        self.assertEqual(report['exit_code'], 0, report)
        self.assertTrue(report['publication_cleanup_confirmed'])
        self.assertFalse(report['capture_started'])


if __name__ == '__main__':
    unittest.main()
